mapper.select:
    	SELECT 
			COUNT(d.DATASET_ID) AS TOTAL_COUNT
		FROM DATASET d 
		WHERE 1=1
			AND STATUS = #{status}
			AND USER_ID = #{user_id}
			AND TITLE LIKE CONCAT('%',#{title},'%')
			AND CONTENTS LIKE CONCAT('%',#{contents},'%')
			AND LABEL_TYPE = #{label_type}
			AND MEDIA_TYPE = #{media_type}
		ORDER BY d.DATASET_ID DESC

